import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";
import { authOptions } from "@/lib/auth-options";

/** Map helper routes are for signed-in dashboard users only (they spend API quota or fetch URLs). */
export async function requireSession(): Promise<NextResponse | null> {
  const session = await getServerSession(authOptions);
  return session ? null : NextResponse.json({ error: "Unauthorized" }, { status: 401 });
}

export function getGoogleMapsKey(): string | null {
  return process.env.GOOGLE_MAPS_API_KEY?.trim() || null;
}

export function readCoordinates(searchParams: URLSearchParams): { lat: number; lng: number } | null {
  const lat = Number(searchParams.get("lat"));
  const lng = Number(searchParams.get("lng"));
  const valid =
    searchParams.get("lat") !== null &&
    searchParams.get("lng") !== null &&
    Number.isFinite(lat) &&
    Number.isFinite(lng) &&
    Math.abs(lat) <= 90 &&
    Math.abs(lng) <= 180;
  return valid ? { lat, lng } : null;
}
