import { NextRequest, NextResponse } from "next/server";
import { getGoogleMapsKey, readCoordinates, requireSession } from "@/lib/maps/server";

const OFFSET = 0.005;
const RADIUS_M = 500;

/** Nearest named place roughly 500 m north, south, east and west of a point (empty when unknown). */
export async function GET(request: NextRequest) {
  const unauthorized = await requireSession();
  if (unauthorized) return unauthorized;

  const coords = readCoordinates(request.nextUrl.searchParams);
  if (!coords) return NextResponse.json({ error: "Invalid coordinates" }, { status: 400 });

  const key = getGoogleMapsKey();
  if (!key) return NextResponse.json({ error: "Nearby search is not configured" }, { status: 503 });

  const directions = {
    north: { lat: coords.lat + OFFSET, lng: coords.lng },
    south: { lat: coords.lat - OFFSET, lng: coords.lng },
    east: { lat: coords.lat, lng: coords.lng + OFFSET },
    west: { lat: coords.lat, lng: coords.lng - OFFSET },
  };
  const language = request.nextUrl.searchParams.get("language") === "ar" ? "ar" : "en";

  const entries = await Promise.all(
    Object.entries(directions).map(async ([name, point]) => {
      try {
        const res = await fetch(
          `https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${point.lat},${point.lng}` +
            `&radius=${RADIUS_M}&language=${language}&key=${key}`,
          { signal: AbortSignal.timeout(8000), cache: "no-store" }
        );
        const data = await res.json();
        return [name, data?.status === "OK" ? data.results?.[0]?.name || "" : ""] as const;
      } catch {
        return [name, ""] as const;
      }
    })
  );

  return NextResponse.json(Object.fromEntries(entries));
}
